"use server";

import { prisma } from "@/src/lib/prisma";
import { revalidatePath } from "next/cache";

export async function createNewTask(data: any) {
  try {
    const user = await prisma.user.findFirst();
    if (!user) return { success: false, error: "User not found" };

    await prisma.task.create({
      data: {
        title: data.titel,
        description: data.documentType, // Tip bilgisini buraya da yazıyoruz
        content: JSON.stringify(data), // Tüm template verisi burada
        sprint: String(data.sprint),
        status: "TODO",
        userId: user.id,
      },
    });

    revalidatePath("/tasks");
    return { success: true };
  } catch (error) {
    console.error("Create Error:", error);
    return { success: false };
  }
}

// Hata aldığın eksik fonksiyon:
export async function deleteTask(id: string) {
  try {
    await prisma.task.delete({
      where: { id },
    });
    revalidatePath("/tasks");
    return { success: true };
  } catch (error) {
    console.error("Delete Error:", error);
    return { success: false };
  }
}

export async function updateTaskContent(id: string, fullData: any) {
  try {
    await prisma.task.update({
      where: { id },
      data: {
        content: JSON.stringify(fullData),
      },
    });
    revalidatePath("/tasks");
    return { success: true };
  } catch (error) {
    return { success: false };
  }
}