"use client";

import { useState } from "react";
import { Card } from "@/components/ui/Card";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Trash2 } from "lucide-react";
import TaskFormModal from "./TaskFormModal";
import { deleteTask, updateTaskContent } from "@/app/actions/task-actions";

export default function TaskListClient({ initialTasks }: { initialTasks: any[] }) {
  const [open, setOpen] = useState(false);
  const [geselecteerdItem, setGeselecteerdItem] = useState<any>(null);

  const handleUpdate = async (id: string, key: string, val: string) => {
    const updated = { ...geselecteerdItem, [key]: val };
    setGeselecteerdItem(updated);
    await updateTaskContent(id, updated);
  };

  const renderFields = (item: any) => {
    const Field = ({ label, fKey }: any) => (
      <div className="space-y-3 group">
        <label className="text-[11px] font-black text-teal-500 uppercase tracking-widest opacity-60">
          {label}
        </label>
        <Textarea
          value={item[fKey] || ""}
          onChange={(e) => handleUpdate(item.id, fKey, e.target.value)}
          className="bg-[#0b1233]/40 border-teal-500/20 focus:border-fuchsia-500/50 min-h-[120px] text-teal-50"
        />
      </div>
    );

    switch (item.documentType) {
      case "review":
        return (
          <>
            <Field label="WAT heb jij gemaakt/geleerd?" fKey="geleerd" />
            <Field label="Wat beheers jij nog niet voldoende?" fKey="nietVoldoende" />
            <Field label="Hoe ga jij dit verhelpen?" fKey="actiepunten" />
          </>
        );
      case "retrospective":
        return (
          <>
            <Field label="Wat ging allemaal goed?" fKey="goed" />
            <Field label="Wat kan beter?" fKey="beter" />
            <Field label="Actiepunt" fKey="actiepunt" />
          </>
        );
      case "sprintplan":
        return (
          <>
            <Field label="Sprint Backlog" fKey="backlog" />
            <Field label="To Do lijst" fKey="todo" />
            <Field label="Definition of Done" fKey="dod" />
          </>
        );
      default: return <p className="text-teal-900 italic">Selecteer een document type.</p>;
    }
  };

  return (
    <div className="min-h-screen bg-[#070B24] text-teal-200 py-10 px-8 flex flex-col items-center">
      <TaskFormModal open={open} setOpen={setOpen} />

      <Card className="w-full max-w-7xl bg-[#0E153A]/60 backdrop-blur-2xl border border-teal-400/30 rounded-2xl shadow-2xl overflow-hidden">
        <div className="grid grid-cols-12 min-h-[800px]">
          
          {/* SIDEBAR */}
          <div className="col-span-3 border-r border-teal-400/10 bg-[#0b1233]/80 p-6 overflow-y-auto">
            <Button onClick={() => setOpen(true)} className="w-full bg-teal-400 text-black font-bold mb-6 hover:bg-teal-300">
              + NIEUW DOCUMENT
            </Button>
            <div className="space-y-3">
              {initialTasks.map((task) => {
                const data = JSON.parse(task.content || "{}");
                return (
                  <div
                    key={task.id}
                    onClick={() => setGeselecteerdItem({ ...data, id: task.id })}
                    className={`p-4 rounded-xl cursor-pointer border transition-all ${geselecteerdItem?.id === task.id ? "border-teal-400 bg-teal-400/10" : "border-transparent bg-white/5 hover:bg-white/10"}`}
                  >
                    <div className="flex justify-between items-start">
                      <div>
                        <div className="text-[10px] font-black text-fuchsia-500 uppercase">{data.documentType}</div>
                        <div className="font-bold text-sm text-teal-100 truncate w-32">{task.title}</div>
                      </div>
                      <button onClick={(e) => { e.stopPropagation(); deleteTask(task.id); }} className="text-teal-900 hover:text-red-500">
                        <Trash2 size={14} />
                      </button>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>

          {/* EDITOR */}
          <div className="col-span-9 p-12 overflow-y-auto">
            {geselecteerdItem ? (
              <div className="max-w-3xl mx-auto space-y-10 animate-in fade-in slide-in-from-right-5">
                <h1 className="text-4xl font-black text-white italic uppercase tracking-tighter">{geselecteerdItem.titel}</h1>
                <div className="space-y-12">{renderFields(geselecteerdItem)}</div>
              </div>
            ) : (
              <div className="h-full flex flex-col items-center justify-center opacity-20">
                <p className="text-2xl font-black uppercase tracking-[0.5em]">Selecteer een doc</p>
              </div>
            )}
          </div>
        </div>
      </Card>
    </div>
  );
}